    async def list_public_tenants(self, *, category: Optional[str] = None, sort: Optional[str] = None, search: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> _m.ListPublicTenantsResponse:
        """List public tenants

        Lists the public tenant directory — every tenant with a public profile, its published agents
        and its marketplace listing row. `category` and `search` filter (search matches name and
        description, case-insensitively), `sort` orders by `recent`, `popular`, `rating` or
        `agents`, and `limit` caps the page at 50 by default and 100 at most. Paging is by opaque
        `cursor`; the response carries `items`, the next `cursor` or null, `has_more` and the
        filtered `total`. The directory is built by a fan-out over the public index and cached
        process-wide for a short window, and the response is sent anonymously with `Cache-Control:
        public, max-age=60`.

        `GET /api/v1/public/tenants`
        """
        return _cast("_m.ListPublicTenantsResponse", await self._client._request(
            "GET",
            "/api/v1/public/tenants",
            query=[("category", category), ("sort", sort), ("search", search), ("limit", limit), ("cursor", cursor)],
            response=_Response(type=_m.ListPublicTenantsResponse),
            request_options=request_options,
        ))

    async def list_public_tenants_all(self, *, category: Optional[str] = None, sort: Optional[str] = None, search: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[_m.PublicTenant]:
        """Every item `list_public_tenants` returns, following the `cursor` cursor until the server
        reports no further pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.list_public_tenants(category=category, sort=sort, search=search, limit=limit, cursor=cursor, request_options=request_options)
            items = page.items or []
            for item in items:
                yield item

            cursor = guard.advance(page.cursor, page.has_more, not items)
            if cursor is None:
                return

